export function getDeptName(deptId) { return departments.find(d => d.id === deptId)?.name || 'Bilinmiyor'; }
export function getDeptIcon(deptId) { return departments.find(d => d.id === deptId)?.icon || '📋'; }
export function getDeptColor(deptId) { return departments.find(d => d.id === deptId)?.color || '#059669'; }
export function getUserName(userId) { return users.find(u => u.id === userId)?.name || 'Bilinmiyor'; }
export function getProductName(productId) { return products.find(p => p.id === productId)?.name || 'Bilinmiyor'; }
export function getProductById(productId) { return products.find(p => p.id === productId); }

export function getStockStatus(product) {
  if (product.quantity <= product.criticalThreshold) return 'critical';
  if (product.quantity <= product.criticalThreshold * 2) return 'warning';
  return 'normal';
}

export function formatDate(dateStr) {
  if (!dateStr) return '\u2014';
  const d = new Date(dateStr);
  return d.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' });
}

export function formatDateTime(dateStr) {
  if (!dateStr) return '\u2014';
  const d = new Date(dateStr);
  return d.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

export function timeAgo(dateStr) {
  const now = new Date();
  const date = new Date(dateStr);
  const diffMs = now - date;
  const diffMins = Math.floor(diffMs / 60000);
  if (diffMins < 60) return diffMins + ' dk once';
  const diffHours = Math.floor(diffMins / 60);
  if (diffHours < 24) return diffHours + ' saat once';
  const diffDays = Math.floor(diffHours / 24);
  return diffDays + ' gun once';
}
